import{z as l,x as A,o as r,c as p,q as n,j as o,D as e,d as E,s,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"期权簿的分层记账","description":"","frontmatter":{"title":"期权簿的分层记账","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-book-layering.md","filePath":"quant/omm-book-layering.md","lastUpdated":1791413859000}'),d={name:"quant/omm-book-layering.md"};function m(h,a,u,g,D,c){const B=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="期权簿的分层记账" tabindex="-1">期权簿的分层记账 <a class="header-anchor" href="#期权簿的分层记账" aria-label="Permalink to &quot;期权簿的分层记账&quot;">​</a></h1><div class="epigraph"><p>账本先于模型：净希腊可以重算，成本与手数不能。轧平那一刻省下的功夫，会在行权、争议与归因那天连本带利还回去。</p><footer>—— 据 Hull, Options, Futures, and Other Derivatives 期权机制与希腊字母各章；分层实务据做市运营整理</footer></div><p><a href="/quant/hfs-map">上一课</a>把高频统计深化收束成估计与应用两条线：已实现方差、噪声修正估计量、跳跃检测与频率选择，归档成台上的输入。输入齐了，台子还缺地基：成交以什么身份落账。本课程从簿记讲起，因为后面的波动仓位、限额、曲线与对冲，都默认「每一手成交可被唯一指认」。本课写期权簿的分层，以及为什么不允许只留净数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成交回报只有事实：合约、方向、张数、价格、时间戳、费用。若账上只维护「净持仓加净希腊」，当天下班看似对得上，缺口几天后出现：一笔平仓消的是哪一批老仓位？跨式拆腿后策略盈亏怎么归？到期被指派，空头看涨去哪了？净数账本回答不了——它把「哪一手」这个维度丢掉了。</p><p>分层的必要性来自三种后续操作：<strong>已实现盈亏</strong>需要每手成本与平仓配对；<strong>归因</strong>需要策略标签（价差的腿还是裸卖）；<strong>审计与争议</strong>需要不可变的原始层。缺层的后果不是不精确，而是无法回答问题。</p><p><span class="marginnote">术语翻译：分层记账就是把「每一手成交从哪来、归到哪去」的流水账，和「现在还剩多少头寸」的汇总账分开记。流水层像购物小票，一张不丢；汇总层像钱包余额，随时可以重算——扔了小票，余额对不上时就再也算不清了。</span></p><h3 id="五层投影" tabindex="-1">五层投影 <a class="header-anchor" href="#五层投影" aria-label="Permalink to &quot;五层投影&quot;">​</a></h3><p>生产账本是一条单向投影链，每层是上一层的确定性函数：</p> \\[\\text{成交层}\\to\\text{手层}\\to\\text{持仓层}\\to\\text{策略层}\\to\\text{盯市层}. \\]<p>成交层只增不改。手层给每笔开仓分配批次：开仓价、策略标签、开平指定（opening / closing）。持仓层按合约净出多空，并保留配对规则——先进先出或指定批次，规则一日一定。策略层把腿绑回组合：卖出平值跨式在持仓层是两行，策略层是一行风险。盯市层才是 <a href="/quant/greeks-hedge">希腊字母</a> 与标记的住址。前置与中台各算一遍，断点必须落在层与层之间，而不是笼统的「对不上」。</p><p><span class="marginnote">被指派的空头看涨不是「仓位消失」：账上要生成一笔按执行价卖出现货的成交，费用并入该批成本；漏记这一步，到期周就有来源不明的盈亏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落账规则按三件事定。其一，<strong>开平指定</strong>：交易所接受 opening / closing 标记，组合单在策略层预登记，腿到齐才成策略，缺腿当天挂「未完成组合」。其二，<strong>配对规则</strong>：FIFO 简单可审计，指定批次用于策略性平仓；规则差异影响已实现盈亏的时间分布，不影响净持仓——净数相同的两个台，明细可以完全不同。其三，<strong>公司行动与到期</strong>：拆股改乘数、除息改 <a href="/quant/discrete-dividend-am">美式行权边界</a>、<a href="/quant/option-exercise-settlement">到期行权与指派</a>，都必须以成交级颗粒度写新条目，不改旧数。</p><p>日终逐层对账：成交对交易所，手层对前台，持仓对托管，盯市对曲线；断掉的层冻结盈亏发布，不用调整分录硬轧平。</p><p><span class="marginnote">数字实例：周一买开 10 张 @$2，周三买开 10 张 @$4，周四平 10 张 @$5。按 FIFO 配对，已实现盈亏是 (5−2)×10=30；指定平周三那批，则只有 (5−4)×10=10。净持仓同样归零，当日已实现盈亏却差三倍——这就是配对规则影响的全部内容。</span></p>',16)),(r(),o(i,null,{default:e(()=>[s(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%88%90%E4%BA%A4%E5%B1%82%20%E5%8F%AA%E5%A2%9E%E4%B8%8D%E6%94%B9%22%5D%20--%3E%20L%5B%22%E6%89%8B%E5%B1%82%20%E6%89%B9%E6%AC%A1%E4%B8%8E%E5%BC%80%E5%B9%B3%22%5D%0A%20%20L%20--%3E%20P%5B%22%E6%8C%81%E4%BB%93%E5%B1%82%20%E5%87%80%E5%A4%B4%E5%AF%B8%22%5D%0A%20%20P%20--%3E%20S%5B%22%E7%AD%96%E7%95%A5%E5%B1%82%20%E8%85%BF%E7%BB%91%E5%9B%9E%E7%BB%84%E5%90%88%22%5D%0A%20%20S%20--%3E%20M%5B%22%E7%9B%AF%E5%B8%82%E5%B1%82%20%E6%A0%87%E8%AE%B0%E4%B8%8E%E5%B8%8C%E8%85%8A%22%5D%0A%20%20M%20--%3E%20B%5B%22%E6%97%A5%E7%BB%88%E9%80%90%E5%B1%82%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20B%20--%3E%7C%E6%96%AD%E7%82%B9%7C%20H%5B%22%E5%86%BB%E7%BB%93%E6%9F%A5%E5%9B%A0%22%5D%0A%20%20B%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20R%5B%22%E5%8F%91%E5%B8%83%E7%9B%88%E4%BA%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("分层为什么值得成本：下游每项工作对应某一层的读取。限额与 "),t("a",{href:"/quant/greeks-hedge"},"希腊聚合"),E(" 读持仓层就够；波动账本要到手层，因为不同批次买入的同一执行价可能带着不同的隐波假设；归因要策略层，否则「跨式卖得贵」与「看涨卖亏了」抵消成糊涂账；审计要成交层的时间戳。层间只允许函数关系：报表可以重组，账本不可重放错。")],-1)),(r(),o(i,null,{default:e(()=>[s(B,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q1%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E7%9B%88%E4%BA%8F%E8%A6%81%E9%85%8D%E5%AF%B9%22%5D%20--%3E%20L2%5B%22%E6%89%8B%E5%B1%82%20%E6%88%90%E6%9C%AC%E4%B8%8E%E6%89%B9%E6%AC%A1%22%5D%0A%20%20Q2%5B%22%E7%AD%96%E7%95%A5%E7%9B%88%E4%BA%8F%E8%A6%81%E5%BD%92%E5%9B%A0%22%5D%20--%3E%20L4%5B%22%E7%AD%96%E7%95%A5%E5%B1%82%20%E8%85%BF%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%0A%20%20Q3%5B%22%E5%AE%A1%E8%AE%A1%E4%BA%89%E8%AE%AE%E8%A6%81%E5%8F%96%E8%AF%81%22%5D%20--%3E%20L1%5B%22%E6%88%90%E4%BA%A4%E5%B1%82%20%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20Q4%5B%22%E9%99%90%E9%A2%9D%E8%A6%81%E8%81%9A%E5%90%88%E5%B8%8C%E8%85%8A%22%5D%20--%3E%20L3%5B%22%E6%8C%81%E4%BB%93%E5%B1%82%20%E5%87%80%E5%A4%B4%E5%AF%B8%22%5D%0A%20%20L2%20--%3E%20OK%5B%22%E5%90%84%E8%AF%BB%E5%90%84%E5%B1%82%20%E4%BA%92%E4%B8%8D%E4%B8%B2%E8%B4%A6%22%5D%0A%20%20L4%20--%3E%20OK%0A%20%20L1%20--%3E%20OK%0A%20%20L3%20--%3E%20OK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>只记净数的台，行权季节发现希腊与成交对不上时，既无法证明错在哪侧，也无法拆分已实现与未实现盈亏，只能全量重放成交救火；而重放的前提，恰恰是成交层从未被污染。</p><p><span class="marginnote">常见误区：初学者容易以为账本越「净」越高级。实际上净数账本等于扔掉小票只留余额——余额本身没错，但行权周希腊与成交对不上时，你既说不清错在哪一侧，也拆不开已实现与未实现盈亏，只能全量重放救火。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>场外账本另有法律层（主协议与净额结算），本课不展开；实物与现金交割的到期条目不同，<a href="/quant/american-exercise">美式</a> 的指派节奏也不同。多腿交易所单由系统拆腿，标签仍需复核；配对规则受税制与监管约束，跨台搬仓要换算。最后，账本不是风险系统：账本回答「持有过什么」，风险系统回答「此刻怕什么」，用账本直接算希腊，是让最慢的一层干最快的活。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>账本是单向投影链：成交只增不改，手层记批次与开平，持仓层净头寸，策略层绑腿，盯市层算风险。</li><li>净数对账必要而不充分；已实现盈亏、归因与审计分别住在手层、策略层与成交层。</li><li>行权、指派、公司行动以成交级颗粒度入账，不允许改写历史。</li><li>配对规则一日一定；规则差异改变盈亏时间分布，不改变净持仓。</li><li>下一课默认账本已立：波动仓位在手层之上按到期与分位折 Vega。</li><li>出处：据 Hull, <em>Options, Futures, and Other Derivatives</em>；分层与对账实务据做市运营整理。</li></ul>',6))])}const F=l(d,[["render",m]]);export{_ as __pageData,F as default};
